def make_op(num1: int, num2: int, op: str):    if op == '+':        return num1 + num2    elif op == '-':        return num1 - num2    return Nonedata = input()plus = data.find('+')minus = data.find('-')operation = []index_operation = []if plus < 0:    operation.insert(0, "-")    operation.insert(0, "-")    index_operation.append(minus)    index_operation.append(data.rfind('-'))elif minus < 0:    operation.insert(0, "+")    operation.insert(0, "+")    index_operation.append(plus)    index_operation.append(data.rfind('+'))elif plus > minus:    operation.append("+")    operation.insert(0, "-")    index_operation.append(minus)    index_operation.append(plus)elif minus > plus:    operation.append("-")    operation.insert(0, "+")    index_operation.append(plus)    index_operation.append(minus)res = make_op(int(data[:index_operation[0]]), int(data[index_operation[0] + 1:index_operation[1]]), operation[0])res = make_op(res, int(data[index_operation[1] + 1:]), operation[1])print(res)